create table if not exists public.science_restart_questions (
  id text primary key,
  subject text not null,
  profile_level text not null,
  knowledge_type text not null,
  topic text not null,
  text text not null,
  options jsonb not null,
  explanation text,
  is_math_heavy boolean,
  text_length text,
  cognitive_skills jsonb not null default '[]'::jsonb,
  difficulty integer,
  active boolean not null default true,
  created_at timestamptz not null default now()
);

create index if not exists science_restart_questions_subject_level_idx
  on public.science_restart_questions (subject, profile_level);

create index if not exists science_restart_questions_topic_idx
  on public.science_restart_questions (topic);

alter table public.science_restart_questions enable row level security;

on conflict (id) do update set
  subject = excluded.subject,
  profile_level = excluded.profile_level,
  knowledge_type = excluded.knowledge_type,
  topic = excluded.topic,
  text = excluded.text,
  options = excluded.options,
  explanation = excluded.explanation,
  is_math_heavy = excluded.is_math_heavy,
  text_length = excluded.text_length,
  cognitive_skills = excluded.cognitive_skills,
  difficulty = excluded.difficulty;

select subject, profile_level, count(*) as question_count
from public.science_restart_questions
group by subject, profile_level
order by subject, profile_level;
